style.css:
@-moz-document domain("pinterest.com") {
:root {
  --my-main-pink: #F76A8B;
  --my-light-pink: #FFD6E0;
  --my-pale-pink: #FFF0F4;
  --my-medium-pink: #F995AC;
  --my-dark-pink: #E94F76;
  --my-deep-pink: #C93660;
}

html,
body,
#app,
[data-test-id="app"] {
  background: var(--my-pale-pink) !important;
}

body {
  color: #71394B !important;
}

a {
  color: var(--my-dark-pink) !important;
}

img {
  border-radius: 14px !important;
}

button {
  border-radius: 20px !important;
}

::selection {
  background: var(--my-main-pink) !important;
  color: white !important;
}
}
